function fmtDay(iso){return +iso.slice(8)+' '+MONTHS[+iso.slice(5,7)-1]}
function plural(n,a,b,c){var m=n%100,k=n%10;return m>10&&m<20?c:k===1?a:k>1&&k<5?b:c}

