/* демо-дата переключается в шапке прототипа; без неё берётся сегодняшняя по Москве */
function nowISO(){return(S&&S.demo)?S.demo:new Date(Date.now()+3*3600e3).toISOString().slice(0,10)}
function nowMs(){return(S&&S.demo)?Date.parse(S.demo+'T12:00:00+03:00'):Date.now()}
function clubOpened(){return nowMs()>=CLUB_OPEN_MS}
function untilOpen(){
 var ms=Math.max(0,CLUB_OPEN_MS-nowMs()),d=Math.floor(ms/864e5),h=Math.floor(ms%864e5/36e5),m=Math.floor(ms%36e5/6e4);
 return d+' '+plural(d,'день','дня','дней')+' '+h+' ч '+m+' мин';
}
function libOpen(x){return x.open||x.date<=nowISO()}
/* статусы события: Скоро, Доступно, Завершено, Запись доступна */
function evStatus(e){
 var t=nowISO();
 if(e.kind==='plaque')return null;
 if(e.d>t)return['soon','Скоро'];
 if(e.d===t)return['open','Доступно'];
 if(e.kind==='game'||e.kind==='qa')return['done','Завершено'];
 if(e.rec)return['rec','Запись доступна'];
 return['open','Доступно'];
}
function eventsOn(iso){return EVENTS.filter(function(e){return e.d===iso})}
function weekDays(n){var w=WEEKS[n],r=[];for(var i=0;i<7;i++)r.push(isoAdd(w.from,i));return r}
function curWeek(){if(S.week!=null)return S.week;return weekOfIso(nowISO())}
function curDay(){var w=WEEKS[curWeek()],t=nowISO();if(S.day&&S.day!=='all'&&S.day>=w.from&&S.day<=w.to)return S.day;return(t>=w.from&&t<=w.to)?t:w.from}

